#include <stddef.h>

struct sceGsDBuff { char data[560]; };
struct nvlMovieSource;
struct nvlMovie;
struct nglTexture;
struct nglQuad { char data[104]; };

enum { NGLTF_32BIT = 1 };

extern "C" void free(void*);
extern "C" void* memalign(unsigned int, unsigned int);
extern "C" int nvlMPEGLoad(char*, void*);
extern "C" nvlMovieSource* nvlLoadMovieSource(const char*, int, void*);
extern "C" nvlMovie* nvlAddMovie(nvlMovieSource*);
extern "C" void nvlReleaseMovieSource(nvlMovieSource*);
extern "C" unsigned int nvlMovieGetWidth(const nvlMovie*);
extern "C" unsigned int nvlMovieGetHeight(const nvlMovie*);
extern "C" nglTexture* nglCreateTexture(unsigned int, unsigned int, unsigned int);
extern "C" void nvlPlayMovie(nvlMovie*, void* (*)(nvlMovie*, size_t*, void*), void*, bool);
extern "C" int nglPrintf(const char*, ...);
extern "C" void* myOutputFunc(nvlMovie*, size_t*, void*);
extern "C" void __assert(const char*, const char*, int);

#define assert(expr) ((expr) ? (void)0 : __assert(#expr, __FILE__, __LINE__))

class movieplayer
{
public:
  void play(char*, bool, bool, bool, int);
private:
  int singleton_pad;
  bool hiRes;
  sceGsDBuff db;
  char* movieBuf;
  nvlMovieSource* movieSource;
  nvlMovie* movie;
  nglTexture* texture;
  nglQuad frame;
  bool movieStarted;
  bool isPlaying;
};

void movieplayer::play( char *filename, bool play_video, bool play_audio, bool loop, int buffersize )
{
  if(hiRes)
  {

    if(nvlMPEGLoad(filename, &db))
    {
			//nvlMPEGSetVolume(ps2MovieVolume);
      movieStarted = true;
      isPlaying    = true;
    }
    else
    {
      movieStarted = false;
      isPlaying    = false;
    }

  }
  else
  {
    if(movieBuf)
      free(movieBuf);
    movieBuf = (char *)memalign(64, buffersize);
    assert(movieBuf);

	  movieSource = nvlLoadMovieSource(filename, buffersize, movieBuf);
    if(movieSource)
	    movie = nvlAddMovie( movieSource );
	  if (!movie)
	  {
		  nglPrintf("WARNING: Could not play movie %s!", filename);
      if(movieSource)
		    nvlReleaseMovieSource(movieSource);
		  movieSource = NULL;
      if(movieBuf)
        free(movieBuf);
      movieBuf = NULL;
		  return;
	  }
	  //nglDev->SetRenderState(D3DRS_YUVENABLE, TRUE);
    texture = nglCreateTexture( NGLTF_32BIT, (unsigned int)nvlMovieGetWidth(movie), (unsigned int)nvlMovieGetHeight(movie) );
	  nvlPlayMovie( movie, myOutputFunc, texture, loop );
	  //nvlMovieSetVolume(movie, nslGetVolume(NSL_SOURCETYPE_MOVIE));
	  movieStarted = true;
    isPlaying    = true;
  }
}
